import unittest

def shipping_fee(order_total):
    # Free delivery from Rs 500, otherwise Rs 40. Negative totals are invalid.
    if order_total < 0:
        raise ValueError("order total cannot be negative")
    if order_total >= 500:
        return 0
    return 40

class TestShippingFee(unittest.TestCase):
    def test_small_order_pays_fee(self):
        self.assertEqual(shipping_fee(200), 40)

    def test_exactly_500_is_free(self):
        self.assertEqual(shipping_fee(500), 0)

    def test_just_below_500_pays(self):
        self.assertEqual(shipping_fee(499), 40)

    def test_negative_total_raises(self):
        with self.assertRaises(ValueError):
            shipping_fee(-1)

