assert "TestShippingFee" in globals(), "Keep the test class name TestShippingFee."
_cls = TestShippingFee
_n = _u.defaultTestLoader.loadTestsFromTestCase(_cls).countTestCases()
assert _n >= 3, f"Write at least 3 test methods whose names start with test_ (found {_n})."
_g = next(v.__globals__ for v in vars(_cls).values() if hasattr(v, "__globals__"))

def _real(t):
    if t < 0:
        raise ValueError("negative")
    return 0 if t >= 500 else 40

def _starts_at_501(t):
    if t < 0:
        raise ValueError("negative")
    return 0 if t > 500 else 40

def _fee_50(t):
    if t < 0:
        raise ValueError("negative")
    return 0 if t >= 500 else 50

def _no_check(t):
    return 0 if t >= 500 else 40

def _passes(fn):
    _g["shipping_fee"] = fn
    r = _u.TestResult()
    _u.defaultTestLoader.loadTestsFromTestCase(_cls).run(r)
    return r.wasSuccessful()

_orig = _g.get("shipping_fee")
try:
    assert _passes(_real), "Your tests should pass on the correct function. Check the expected values: under 500 costs 40, 500 and above is free."
    assert not _passes(_starts_at_501), "Your tests still pass when free delivery wrongly starts at 501. Add a test for an order of exactly 500."
    assert not _passes(_fee_50), "Your tests still pass when the fee is 50 instead of 40. Check the fee on a small order."
    assert not _passes(_no_check), "Your tests still pass when negative totals are accepted. Use assertRaises(ValueError) with a negative total."
finally:
    _g["shipping_fee"] = _orig

