import unittest

class Wallet:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def top_up(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        self.balance += amount

    def pay(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        if amount > self.balance:
            raise ValueError("insufficient balance")
        self.balance -= amount

class TestWallet(unittest.TestCase):
    def setUp(self):
        self.wallet = Wallet("Riya", balance=100)

    def test_starts_with_balance(self):
        self.assertEqual(self.wallet.owner, "Riya")
        self.assertEqual(self.wallet.balance, 100)

    def test_new_wallet_defaults_to_zero(self):
        self.assertEqual(Wallet("Arjun").balance, 0)

    def test_top_up_adds_money(self):
        self.wallet.top_up(50)
        self.assertEqual(self.wallet.balance, 150)

    def test_pay_reduces_balance(self):
        self.wallet.pay(30)
        self.assertEqual(self.wallet.balance, 70)

    def test_cannot_pay_more_than_balance(self):
        with self.assertRaises(ValueError):
            self.wallet.pay(500)
        self.assertEqual(self.wallet.balance, 100)

    def test_top_up_must_be_positive(self):
        with self.assertRaises(ValueError):
            self.wallet.top_up(0)

unittest.main(argv=["x"], exit=False)
